import React, { useEffect, useState } from 'react';
import Comments from '../../components/Comments/Comments';
import { listAll } from '@/services/ForumService';
import './Forum.css';

const ForumIndexPage: React.FC = () => {
  const [forums, setForums] = useState<any[]>([]);

  useEffect(() => {
    fetchForums();
  }, []);

  const fetchForums = async () => {
    try {
      const forumsData = await listAll();
      setForums(forumsData);
    } catch (error) {
      console.error('Erro ao buscar fóruns:', error);
    }
  };

  return (
    <div className="forum-index-page">
      <div className="forum-content">
        <h1>Fóruns Disponíveis</h1>
        
        {/* Tabela de Fóruns */}
        <div className="forums-table-container">
          <table className="forums-table">
            <thead>
              <tr>
                <th>ID</th>
                <th>Título</th>
                <th>Descrição</th>
                <th>Autor</th>
                <th>Filme Relacionado</th>
                <th>Ações</th>
              </tr>
            </thead>
            <tbody>
              {forums.map((forum) => (
                <tr key={forum.id}>
                  <td>{forum.id}</td>
                  <td>{forum.title}</td>
                  <td>{forum.description}</td>
                  <td>{forum.username}</td>
                  <td>{forum.related_movie?.name || 'N/A'}</td>
                  <td>
                    <button 
                      className="view-forum-btn"
                      onClick={() => window.location.href = `/forum/${forum.id}`}
                    >
                      Ver Fórum
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
        
        {/* Seção de comentários */}
        <Comments />
      </div>
    </div>
  );
};

export default ForumIndexPage;